const unsigned char FLAG_ACTIVE = 0x04; // 0000 0100
const unsigned char FLAG_HIDDEN = 0x08;  // 0000 1000

// Data containing several flags
unsigned char status = 0b10101100;

// 1. Checking if a specific flag is set (Masking)
// Result is non-zero (4) if FLAG_ACTIVE is set
int active_check = status & FLAG_ACTIVE;

// 2. Extracting lower nibble (4 bits)
const int NIBBLE_MASK = 0x0F; // 0000 1111
int lower_data = status & NIBBLE_MASK; // 0b1100 (12)

// 3. Fast parity check
int is_odd = status & 1; // 0 (False)
